     "ponto": "DBA26-PEN-3.6",
     "tema": "Causa superveniente relativamente independente",
     "assertiva": "A superveniência de causa relativamente independente que, por si só, produz o resultado exclui a imputação do resultado, mas o agente responde pelos atos já praticados.",
