     "id": "PEN-3.6-R1-04",
     "ponto": "DBA26-PEN-3.6",
     "tema": "Omissão imprópria: dever de agir",
     "assertiva": "O dever de agir para evitar o resultado incumbe a quem tenha por lei obrigação de cuidado, proteção ou vigilância, a quem de outra forma assumiu a responsabilidade de impedir o resultado e a quem, com seu comportamento anterior, criou o risco.",
