     "tema": "Causas interruptivas",
     "assertiva": "Interrompem a prescrição o recebimento da denúncia ou queixa, a pronúncia, a decisão confirmatória da pronúncia, a publicação da sentença ou acórdão condenatórios recorríveis, o início ou continuação do cumprimento da pena e a reincidência.",
